raw_definition.expression:
ifelse(
{product_code} = 'AmazonRDS' AND contains({usage_type},'ExtendedSupport'), 'RDS Extended Support',
{product_code} = 'AmazonRDS' AND endsWith({usage_type},'Data-API-Usage'), 'RDS Data API',
{product_family}
)

ifelse(
{product_code} = 'AmazonDRS' AND startsWith({usage_type},'Extended Support'), 'RDS Extended Support',
{product_family}
)

ifelse(
${AIMLBedrockGroupBy} = 'Account', Account,
${AIMLBedrockGroupBy} = 'Region', region,
${AIMLBedrockGroupBy} = 'Usage Type Group', {Bedrock UsageType Group},
${AIMLBedrockGroupBy} = 'Model/Resource Group', {Bedrock Resource Group},
${AIMLBedrockGroupBy} = 'Pricing Model', {Bedrock Pricing Model},
${AIMLBedrockGroupBy} = 'Legal Entity', {legal_entity},
// Add ${AIMLBedrockGroupBy}
NULL
)

ifelse(
${DatabasesGroupBy} = 'Instance Type', {instance_type},
${DatabasesGroupBy} = 'Instance Family', {Databases Instance Family},
${DatabasesGroupBy} = 'Processor Type', {Processor Type},
{instance_type}
)

ifelse(
locate({usage_type},'-') <= 5, substring({usage_type},locate({usage_type},'-')+1,strlen({usage_type})), // remove region in front
{usage_type}
)

ifelse(
${AIMLDevExpirienceGroupBy} = 'Account', Account,
${AIMLDevExpirienceGroupBy} = 'Region', region,
${AIMLDevExpirienceGroupBy} = 'Usage Type Group', {Developer Experience Usage Type Group},
${AIMLDevExpirienceGroupBy} = 'Charge Type Group', {Charge Type Group},
// Add ${AIMLDevExpirienceGroupBy}
NULL
)

ifelse(
    ${TrendsGroupBy1} = 'Service', {Product Code Pretty},
    ${TrendsGroupBy1} = 'Account', Account,
    ${TrendsGroupBy1} = 'Payer Account', {payer_account_id},
    ${TrendsGroupBy1} = 'Service Category', {Service Category},
    // Add ${TrendsGroupBy1}
    NULL
 )

//Assumes item_description follows a pattern
//USD 0.0538 hourly fee per Aurora PostgreSQL, db.r6i.large instance
//USD 0.xx hourly fee per PostgreSQL, db.r6i.large instance
//USD 0.xx hourly fee per MySQL, db.r6i.large instance
//USD 0.xx hourly fee per Oracle, db.r6i.large instance
//USD 0.xx hourly fee per SQL Server, db.r6i.large instance
//USD 0.xx hourly fee per MariaDB, db.r6i.large instance
//Extracts the string between "per" and the next comma
substring(
    {item_description},
    locate({item_description}, 'per ') + 4,
    locate({item_description}, ',') - (locate({item_description}, 'per ') + 4)
)

ifelse(
    {product_name} = 'Amazon Elasticsearch Service', 'Amazon OpenSearch Service',
    isNull({product_name}) OR {product_name} = '', {Product Code Pretty},
    {product_name}
)

ifelse(
    ${TrendsGroupBy2} = 'Service', {Product Code Pretty},
    ${TrendsGroupBy2} = 'Account', Account,
    ${TrendsGroupBy2} = 'Payer Account', {payer_account_id},
    ${TrendsGroupBy2} = 'Service Category', {Service Category},
    // Add ${TrendsGroupBy2}
    NULL
 )

ifelse(
    contains({usage_type},"TrSpt"), "Managed Spot Training", {Purchase Option Sorted}
)

ifelse(
${AIMLSagemakerGroupBy} = 'Account', Account,
${AIMLSagemakerGroupBy} = 'Region', region,
${AIMLSagemakerGroupBy} = 'Usage Type Group', {SageMaker Usage Type Group},
${AIMLSagemakerGroupBy} = 'Charge Type Group', {Charge Type Group},
// Add ${AIMLSagemakerGroupBy}
NULL
)

ifelse(
${DatabasesSummaryGroupBy} = 'Account', Account,
${DatabasesSummaryGroupBy} = 'Region', region,
${DatabasesSummaryGroupBy} = 'Database Engine', {Database Engine},
${DatabasesSummaryGroupBy} = 'Charge Type Group', {Charge Type Group},
${DatabasesSummaryGroupBy} = 'Service', {Product Code Pretty},
// Add ${DatabasesSummaryGroupBy}
NULL
)

ifelse(
    contains(toLower({Bedrock Pricing Unit}),'token'), '1M Tokens',
    {Bedrock Pricing Unit}
)

ifelse(
    {product_name} = 'Amazon Elasticsearch Service', 'Amazon OpenSearch Service',
    isNull({product_name}) OR {product_name} = '', {Product Code Pretty},
    {product_name}
)

ifelse(
${AIMLBedrockGroupBy} = 'Account', Account,
${AIMLBedrockGroupBy} = 'Region', region,
${AIMLBedrockGroupBy} = 'Usage Type Group', {Bedrock UsageType Group},
${AIMLBedrockGroupBy} = 'Model/Resource Group', {Bedrock Resource Group},
${AIMLBedrockGroupBy} = 'Pricing Model', {Bedrock Pricing Model},
${AIMLBedrockGroupBy} = 'Legal Entity', {legal_entity},
// Add ${AIMLBedrockGroupBy}
NULL
)

ifelse(
${BillingSummaryGroupBy} = 'Charge Type Group', {Charge Type Group},
${BillingSummaryGroupBy} = 'Payer Account', {payer_account_id},
${BillingSummaryGroupBy} = 'Service Category', {Service Category},
// Add ${BillingSummaryGroupBy}
NULL
)

ifelse(
${TaxonomyExplorerGroupBy2} = 'Account', Account,
${TaxonomyExplorerGroupBy2} = 'Service Category', {Service Category},
${TaxonomyExplorerGroupBy2} = 'Service', {Product Code Pretty},
${TaxonomyExplorerGroupBy2} = 'Region', region,
${TaxonomyExplorerGroupBy2} = 'Charge Type Group', {Charge Type Group},
// Add ${TaxonomyExplorerGroupBy2}
NULL
)

ifelse(
    contains({usage_type},"TrSpt"), "Managed Spot Training", {Purchase Option Sorted}
)

ifelse(
{billing_entity} = 'AWS Marketplace' and  contains({product_name},'Bedrock'), 'Amazon Bedrock',
{Product Code Pretty}
)

//Assumes UsageType follows a pattern
//HeavyUsage:db.m6gd.large
//HeavyUsage:db.r5.large
//HeavyUsage:db.t3.micro
//Fetches the substring after the colon, then after the first dot to get the instance family
split(split({usage_type}, ':', 2), '.', 2)

ifelse(
{Amazon Glacier Cost} - {S3 Glacier Deep Archive Estimated Cost} < 0, 0,
{Amazon Glacier Cost} - {S3 Glacier Deep Archive Estimated Cost}
)

ifelse(
${DatabasesGroupBy} = 'Instance Type', {instance_type},
${DatabasesGroupBy} = 'Instance Family', {Databases Instance Family},
${DatabasesGroupBy} = 'Processor Type', {Processor Type},
{instance_type}
)

ifelse(
countOver({WorkSpaces Pricing Unit},[{Workspace ID}],PRE_AGG) > 2,
'Changed',
{Workspaces Running Mode}
)

ifelse(
${AIMLDevExpirienceGroupBy} = 'Account', Account,
${AIMLDevExpirienceGroupBy} = 'Region', region,
${AIMLDevExpirienceGroupBy} = 'Usage Type Group', {Developer Experience Usage Type Group},
${AIMLDevExpirienceGroupBy} = 'Charge Type Group', {Charge Type Group},
// Add ${AIMLDevExpirienceGroupBy}
NULL
)

ifelse(
locate({usage_type},'-') <= 5, substring({usage_type},locate({usage_type},'-')+1,strlen({usage_type})), // remove region in front
{usage_type}
)

ifelse(
    contains({usage_type},"TrSpt"), "Managed Spot Training", {Purchase Option Sorted}
)

ifelse(
${TaxonomyExplorerGroupBy1} = 'Account', Account,
${TaxonomyExplorerGroupBy1} = 'Service Category', {Service Category},
${TaxonomyExplorerGroupBy1} = 'Service', {Product Code Pretty},
${TaxonomyExplorerGroupBy1} = 'Region', region,
${TaxonomyExplorerGroupBy1} = 'Charge Type Group', {Charge Type Group},
// Add ${TaxonomyExplorerGroupBy1}
NULL
)

ifelse(
    ${TrendsGroupBy2} = 'Service', {Product Code Pretty},
    ${TrendsGroupBy2} = 'Account', Account,
    ${TrendsGroupBy2} = 'Payer Account', {payer_account_id},
    ${TrendsGroupBy2} = 'Service Category', {Service Category},
    // Add ${TrendsGroupBy2}
    NULL
 )

ifelse(
${AIMLSagemakerGroupBy} = 'Account', Account,
${AIMLSagemakerGroupBy} = 'Region', region,
${AIMLSagemakerGroupBy} = 'Usage Type Group', {SageMaker Usage Type Group},
${AIMLSagemakerGroupBy} = 'Charge Type Group', {Charge Type Group},
// Add ${AIMLSagemakerGroupBy}
NULL
)

ifelse(
    ${TrendsGroupBy1} = 'Service', {Product Code Pretty},
    ${TrendsGroupBy1} = 'Account', Account,
    ${TrendsGroupBy1} = 'Payer Account', {payer_account_id},
    ${TrendsGroupBy1} = 'Service Category', {Service Category},
    // Add ${TrendsGroupBy1}
    NULL
 )

ifelse(
${DatabasesSummaryGroupBy} = 'Account', Account,
${DatabasesSummaryGroupBy} = 'Region', region,
${DatabasesSummaryGroupBy} = 'Database Engine', {Database Engine},
${DatabasesSummaryGroupBy} = 'Charge Type Group', {Charge Type Group},
${DatabasesSummaryGroupBy} = 'Service', {Product Code Pretty},
// Add ${DatabasesSummaryGroupBy}
NULL
)

//Assumes UsageType follows a pattern
//HeavyUsage:ra3.xlplus
//USW2-HeavyUsage:ra3.xlplus
//EUC1-HeavyUsage:ra3.4xlplus
//Extracts the instance type string after the colon
split({usage_type}, ':', 2)

ifelse(
    contains(toLower({Bedrock Pricing Unit}),'token'), '1M Tokens',
    {Bedrock Pricing Unit}
)

// https://aws.amazon.com/blogs/aws/new-aws-public-ipv4-address-charge-public-ip-insights/
ifelse(
    contains({usage_type}, "PublicIPv4"), ifelse(
        Cost = 0 AND contains({usage_type}, "InUseAddress"), {usage_quantity} * 0.005, //projected
        Cost = 0, 0, // idle address covered by ElasticIP
        Cost
    ),
    contains({usage_type}, "ElasticIP"), Cost,
    NULL
)
